37: /** 资产账户、手工流水与每日收益计提的领域服务。 */
38: @Service
39: @RequiredArgsConstructor
40: public class FinanceService {
41: 
42:     /** 日报使用的当前资产余额与指定自然日账户流水。 */
43:     public record DailyAssetData(List<FinanceAccount> accounts, List<FinanceTransaction> transactions) {}
44: 
45:     private static final Set<String> ACCOUNT_TYPES = Set.of(
46:             "wechat_balance", "wechat_yield", "alipay_balance", "alipay_yuebao", "bank", "other",
47:             "wechat", "alipay", "cash");
48:     private static final Set<String> TRANSACTION_TYPES = Set.of("income", "expense");
49:     private static final Set<String> ADJUSTMENT_DIRECTIONS = Set.of("increase", "decrease");
50:     private static final BigDecimal DAYS_PER_YEAR = new BigDecimal("36500");
51: 
52:     private final FinanceRepository repository;
53:     private final ExpenseAnalyticsService expenseAnalyticsService;
54:     private final DailyEventService dailyEventService;
55: 
56:     /** 旧日历花销在财务流水中使用的前缀，用于区分真实财务流水 id。 */
57:     private static final String CALENDAR_TRANSACTION_PREFIX = "calendar-";
58: 
59:     /** 查询财务总览；读取前先补齐所有生息账户截至今日的收益。 */
60:     @Transactional
61:     public FinanceOverview getOverview(String ownerId) {
62:         requireOwner(ownerId);
63:         LocalDate today = LocalDate.now();
64:         settleYieldThrough(ownerId, today);
65:         List<FinanceAccount> accounts = repository.findAccounts(ownerId);
66:         BigDecimal totalAssets = accounts.stream()
67:                 .map(FinanceAccount::balance)
68:                 .reduce(BigDecimal.ZERO, BigDecimal::add);
69:         LocalDate monthStart = today.withDayOfMonth(1);
70:         MonthTotals totals = repository.summarizeMonth(ownerId, monthStart, monthStart.plusMonths(1));
71:         BigDecimal monthExpense = expenseAnalyticsService
72:                 .analyze(ownerId, monthStart, monthStart.plusMonths(1).minusDays(1)).totalExpense();
73:         return new FinanceOverview(totalAssets, totals.income(), monthExpense, totals.yield(),
74:                 accounts, findRecentTransactions(ownerId));
75:     }
76: 
77:     /** 按本周、本月或今年返回连续日期的收支趋势和支出分类堆叠数据。 */
78:     @Transactional
79:     public ExpenseChart getExpenseChart(String ownerId, String range) {
80:         requireOwner(ownerId);
81:         String normalizedRange = range == null || range.isBlank() ? "month" : range.trim().toLowerCase();
82:         LocalDate today = LocalDate.now();
83:         LocalDate from = chartStart(normalizedRange, today);
84:         settleYieldThrough(ownerId, today);
85:         var analysis = expenseAnalyticsService.analyze(ownerId, from, today);
86:         Map<LocalDate, BigDecimal> incomeByDate = repository
87:                 .findDailyIncomeTotals(ownerId, from, today.plusDays(1)).stream()
88:                 .collect(Collectors.toMap(DailyIncomeTotal::date, DailyIncomeTotal::amount));
89:         List<ExpenseChartDay> days = analysis.days().stream().map(day -> new ExpenseChartDay(
90:                 day.date(), day.total(), incomeByDate.getOrDefault(day.date(), BigDecimal.ZERO),
91:                 day.categories().entrySet().stream()
92:                 .map(item -> new ExpenseCategoryAmount(item.getKey(), item.getValue())).toList())).toList();
93:         BigDecimal totalIncome = incomeByDate.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
94:         return new ExpenseChart(normalizedRange, from, today, analysis.totalExpense(), totalIncome, days,
95:                 repository.findTransactionCategoryColors(ownerId, "expense"));
96:     }
97: 
98:     /** 补齐收益后查询期间内各账户收支，以及全口径支出排行。 */
99:     @Transactional
100:     public ExpenseInsights getExpenseInsights(String ownerId, String range) {
101:         requireOwner(ownerId);
102:         String normalizedRange = range == null || range.isBlank() ? "month" : range.trim().toLowerCase();
103:         if (!Set.of("week", "month", "year").contains(normalizedRange)) {
104:             throw new IllegalArgumentException("支出分析时间范围仅支持 week、month 或 year");
105:         }
106:         LocalDate today = LocalDate.now();
107:         LocalDate from = chartStart(normalizedRange, today);
108:         settleYieldThrough(ownerId, today);
109:         var expenses = expenseAnalyticsService.reportExpenses(ownerId, from, today);
110:         List<RankedExpense> transactions = expenses.stream()
111:                 .sorted(Comparator.comparing(ExpenseAnalyticsService.ExpenseEntry::amount).reversed()
112:                         .thenComparing(ExpenseAnalyticsService.ExpenseEntry::date, Comparator.reverseOrder())
113:                         .thenComparing(ExpenseAnalyticsService.ExpenseEntry::id))
114:                 .map(entry -> new RankedExpense(entry.id(), entry.note(), entry.category(),
115:                         entry.date(), entry.amount(), entry.source())).toList();
116:         Map<String, BigDecimal> byCategory = expenses.stream().collect(Collectors.toMap(
117:                 ExpenseAnalyticsService.ExpenseEntry::category,
118:                 ExpenseAnalyticsService.ExpenseEntry::amount, BigDecimal::add));
119:         List<ExpenseCategoryAmount> categories = byCategory.entrySet().stream()
120:                 .sorted(Map.Entry.<String, BigDecimal>comparingByValue().reversed()
121:                         .thenComparing(Map.Entry::getKey))
122:                 .map(entry -> new ExpenseCategoryAmount(entry.getKey(), entry.getValue())).toList();
123:         BigDecimal total = expenses.stream().map(ExpenseAnalyticsService.ExpenseEntry::amount)
124:                 .reduce(BigDecimal.ZERO, BigDecimal::add);
125:         return new ExpenseInsights(normalizedRange, from, today,
126:                 repository.findAccountExpenses(ownerId, from, today), transactions, categories, total);
127:     }
