129:     private LocalDate chartStart(String range, LocalDate today) {
130:         return switch (range) {
131:             case "today" -> today;
132:             case "week" -> today.minusDays(today.getDayOfWeek().getValue() - 1L);
133:             case "month" -> today.withDayOfMonth(1);
134:             case "year" -> today.withDayOfYear(1);
135:             default -> throw new IllegalArgumentException("图表时间范围仅支持 today、week、month 或 year");
136:         };
137:     }
