139:     private List<FinanceTransaction> findRecentTransactions(String ownerId) {
140:         List<FinanceTransaction> transactions = new ArrayList<>(repository.findTransactions(ownerId, 100));
141:         expenseAnalyticsService.findRecentCalendarExpenses(ownerId, 100).forEach(expense -> transactions.add(
142:                 new FinanceTransaction("calendar-" + expense.id(), "", "日历记录", expense.date(), expense.time(),
143:                         "expense", expense.category(), expense.note(), expense.amount(), expense.currency(),
144:                         "calendar", expense.createdAt())));
145:         Comparator<FinanceTransaction> newestFirst = Comparator.comparing(FinanceTransaction::date)
146:                 .thenComparing(FinanceTransaction::time)
147:                 .thenComparing(FinanceTransaction::createdAt)
148:                 .reversed();
149:         return transactions.stream().sorted(newestFirst).limit(100).toList();
150:     }
