152:     /** 查询完整流水，并合并仍由旧日历入口保存的花销记录。 */
153:     @Transactional(readOnly = true)
154:     public List<FinanceTransaction> getTransactions(String ownerId) {
155:         requireOwner(ownerId);
156:         List<FinanceTransaction> transactions = new ArrayList<>(repository.findAllTransactions(ownerId));
157:         expenseAnalyticsService.findAllCalendarExpenses(ownerId).forEach(expense -> transactions.add(
158:                 new FinanceTransaction("calendar-" + expense.id(), "", "日历记录", expense.date(), expense.time(),
159:                         "expense", expense.category(), expense.note(), expense.amount(), expense.currency(),
160:                         "calendar", expense.createdAt())));
161:         Comparator<FinanceTransaction> newestFirst = Comparator.comparing(FinanceTransaction::date)
162:                 .thenComparing(FinanceTransaction::time)
163:                 .thenComparing(FinanceTransaction::createdAt)
164:                 .reversed();
165:         return transactions.stream().sorted(newestFirst).toList();
166:     }
