168:     /** 按日读取资产变动，包含划账与校准，不混入无账户的旧日历花销。 */
169:     @Transactional(readOnly = true)
170:     public List<FinanceTransaction> getDayTransactions(String ownerId, LocalDate date) {
171:         requireOwner(ownerId);
172:         if (date == null) throw new IllegalArgumentException("日期不能为空");
173:         return repository.findDayTransactions(ownerId, date);
