176:     /** 按日报任务时区结清收益后，读取当前资产余额和指定自然日的账户流水。 */
177:     @Transactional
178:     public DailyAssetData getDailyAssetData(String ownerId, LocalDate date) {
179:         requireOwner(ownerId);
180:         if (date == null) throw new IllegalArgumentException("日期不能为空");
181:         settleYieldThrough(ownerId, date);
182:         return new DailyAssetData(repository.findAccounts(ownerId), repository.findDayTransactions(ownerId, date));
183:     }
