185:     /** 当前账本可回溯的账户余额，账户名称使用当前名称，避免同名账户合并。 */
186:     public record ReportAsset(String id, String name, String currency, BigDecimal balance) {}
187: 
188:     /** 只读回溯日末余额；不补计收益、不写快照，不把当前余额冒充历史余额。 */
189:     @Transactional(readOnly = true)
190:     public List<ReportAsset> getReportAssets(String ownerId, LocalDate date, java.time.ZoneId zone) {
191:         requireOwner(ownerId);
192:         if (date == null || zone == null) throw new IllegalArgumentException("日期与时区不能为空");
193:         Map<String, BigDecimal> balances = repository.findBalancesAt(ownerId, date);
194:         return repository.findAccounts(ownerId).stream()
195:                 .filter(account -> !account.createdAt().atZone(zone).toLocalDate().isAfter(date))
196:                 .map(account -> new ReportAsset(account.id(), account.name(), account.currency(), balances.get(account.id())))
197:                 .toList();
198:     }
