200:     /** 周期报告仅取指定区间的账户流水；旧日历支出由支出投影提供，不重复合并。 */
201:     @Transactional(readOnly = true)
202:     public List<FinanceTransaction> getReportTransactions(String ownerId, LocalDate from, LocalDate to) {
203:         requireOwner(ownerId);
204:         if (from == null || to == null || from.isAfter(to)
205:                 || java.time.temporal.ChronoUnit.DAYS.between(from, to) > 366)
206:             throw new IllegalArgumentException("报告日期范围不合法");
207:         return repository.findRangeTransactions(ownerId, from, to);
208:     }
