210:     /** 查询最多一年内的轻量收支汇总，与财务图表复用统计来源。 */
211:     @Transactional(readOnly = true)
212:     public CashflowSummary getCashflowSummary(
213:             String ownerId, LocalDate from, LocalDate to) {
214:         requireOwner(ownerId);
215:         if (from == null || to == null || from.isAfter(to)
216:                 || java.time.temporal.ChronoUnit.DAYS.between(from, to) > 366) {
217:             throw new IllegalArgumentException("日期范围不合法，最多查询一年");
218:         }
219:         BigDecimal income = repository.findDailyIncomeTotals(ownerId, from, to.plusDays(1)).stream()
220:                 .map(DailyIncomeTotal::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
221:         return new CashflowSummary(
222:                 income, expenseAnalyticsService.analyze(ownerId, from, to).totalExpense());
223:     }
