243:     /** 创建资产账户；年化率使用百分数表达，例如 1.85 表示 1.85%。 */
244:     @Transactional
245:     public FinanceAccount createAccount(
246:             String ownerId, String name, String accountType, String currency, BigDecimal initialBalance,
247:             boolean interestEnabled, BigDecimal annualRatePercent) {
248:         requireOwner(ownerId);
249:         if (name == null || name.isBlank()) throw new IllegalArgumentException("账户名称不能为空");
250:         if (!ACCOUNT_TYPES.contains(accountType)) throw new IllegalArgumentException("账户类型不合法");
251:         String normalizedCurrency = normalizeCurrency(currency);
252:         BigDecimal balance = requireMoney(initialBalance, true, "初始余额");
253:         BigDecimal rate = annualRatePercent == null ? BigDecimal.ZERO : annualRatePercent;
254:         if (rate.signum() < 0 || rate.compareTo(new BigDecimal("100")) > 0 || rate.scale() > 6) {
255:             throw new IllegalArgumentException("年化收益率必须在 0% 到 100% 之间且最多六位小数");
256:         }
257:         if (!interestEnabled) rate = BigDecimal.ZERO;
258:         String id = UUID.randomUUID().toString();
259:         Instant now = Instant.now();
260:         repository.insertAccount(id, ownerId, name.trim(), accountType, normalizedCurrency, toMinor(balance),
261:                 interestEnabled, rate.stripTrailingZeros(), LocalDate.now(), now);
262:         return repository.findAccount(ownerId, id)
263:                 .orElseThrow(() -> new IllegalStateException("账户创建后无法读取"));
264:     }
