498:     @Transactional
499:     public List<FinanceTransaction> transfer(
500:             String ownerId, String fromAccountId, String toAccountId, BigDecimal amount,
501:             String note, LocalDate date, LocalTime time) {
502:         requireOwner(ownerId);
503:         if (fromAccountId == null || fromAccountId.isBlank()) throw new IllegalArgumentException("转出账户不能为空");
504:         if (toAccountId == null || toAccountId.isBlank()) throw new IllegalArgumentException("转入账户不能为空");
505:         if (fromAccountId.trim().equals(toAccountId.trim())) {
506:             throw new IllegalArgumentException("转出账户与转入账户不能相同");
507:         }
508:         if (date == null || time == null) throw new IllegalArgumentException("流水日期和时间不能为空");
509:         BigDecimal normalizedAmount = requireMoney(amount, false, "划账金额");
510: 
511:         FinanceAccount fromAccount = repository.findAccount(ownerId, fromAccountId.trim())
512:                 .orElseThrow(() -> new IllegalArgumentException("转出账户不存在"));
513:         FinanceAccount toAccount = repository.findAccount(ownerId, toAccountId.trim())
514:                 .orElseThrow(() -> new IllegalArgumentException("转入账户不存在"));
515: 
516:         if (!fromAccount.currency().equalsIgnoreCase(toAccount.currency())) {
517:             throw new IllegalArgumentException("不同币种账户之间暂不支持划账");
518:         }
519: 
520:         LocalDate today = LocalDate.now();
521:         accrueYield(ownerId, fromAccount, today);
522:         accrueYield(ownerId, toAccount, today);
523: 
524:         long amountMinor = toMinor(normalizedAmount);
525:         Instant now = Instant.now();
526: 
527:         if (!repository.adjustBalance(ownerId, fromAccount.id(), -amountMinor, now)) {
528:             throw new IllegalArgumentException("转出账户余额不足，无法划账");
529:         }
530:         repository.adjustBalance(ownerId, toAccount.id(), amountMinor, now);
531: 
532:         String trimmedNote = note != null ? note.trim() : "";
533:         if (trimmedNote.length() > 100) throw new IllegalArgumentException("说明不能超过 100 个字符");
534:         String outNote = !trimmedNote.isEmpty() ? trimmedNote : "划账至 " + toAccount.name();
535:         String inNote = !trimmedNote.isEmpty() ? trimmedNote : "从 " + fromAccount.name() + " 划入";
536: 
537:         String fromTransactionId = UUID.randomUUID().toString();
538:         String toTransactionId = UUID.randomUUID().toString();
539:         String pairId = UUID.randomUUID().toString();
540: 
541:         repository.insertTransaction(fromTransactionId, ownerId, fromAccount.id(), date, time,
542:                 "transfer_out", "划账", outNote, amountMinor, fromAccount.currency(), "manual", pairId, now);
543:         repository.insertTransaction(toTransactionId, ownerId, toAccount.id(), date, time,
544:                 "transfer_in", "划账", inNote, amountMinor, toAccount.currency(), "manual", pairId, now);
545: 
546:         FinanceTransaction fromTx = new FinanceTransaction(fromTransactionId, fromAccount.id(), fromAccount.name(),
547:                 date, time, "transfer_out", "划账", outNote, normalizedAmount, fromAccount.currency(),
548:                 "manual", now);
549: 
550:         FinanceTransaction toTx = new FinanceTransaction(toTransactionId, toAccount.id(), toAccount.name(),
551:                 date, time, "transfer_in", "划账", inNote, normalizedAmount, toAccount.currency(),
552:                 "manual", now);
