557:     /** 补齐指定日期前尚未计提的账户收益，供总览读取和未来定时任务复用。 */
558:     @Transactional
559:     public void settleYieldThrough(String ownerId, LocalDate throughDate) {
560:         requireOwner(ownerId);
561:         if (throughDate == null) throw new IllegalArgumentException("收益计提日期不能为空");
562:         repository.findAccounts(ownerId).forEach(account -> accrueYield(ownerId, account, throughDate));
563:     }
564: 
565:     private void accrueYield(String ownerId, FinanceAccount account, LocalDate today) {
566:         if (!account.interestEnabled() || account.annualRatePercent().signum() <= 0
567:                 || !account.lastAccrualDate().isBefore(today)) return;
568:         BigDecimal runningBalance = account.balance();
569:         LocalDate date = account.lastAccrualDate().plusDays(1);
570:         Instant now = Instant.now();
571:         while (!date.isAfter(today)) {
572:             BigDecimal yield = runningBalance.multiply(account.annualRatePercent())
573:                     .divide(DAYS_PER_YEAR, 2, RoundingMode.HALF_UP);
574:             if (yield.signum() > 0) {
575:                 long yieldMinor = toMinor(yield);
576:                 repository.insertTransaction(UUID.randomUUID().toString(), ownerId, account.id(), date,
577:                         LocalTime.of(0, 0), "yield", "理财收益", account.name() + " 每日收益",
578:                         yieldMinor, account.currency(), "automatic", null, now);
579:                 runningBalance = runningBalance.add(yield);
580:             }
581:             date = date.plusDays(1);
582:         }
583:         repository.updateBalanceAndAccrualDate(ownerId, account.id(), toMinor(runningBalance), today, now);
584:     }
585: 
586:     private BigDecimal requireMoney(BigDecimal value, boolean allowZero, String field) {
587:         if (value == null || value.scale() > 2 || (allowZero ? value.signum() < 0 : value.signum() <= 0)) {
588:             throw new IllegalArgumentException(field + (allowZero ? "不能小于零且最多保留两位小数" : "必须大于零且最多保留两位小数"));
589:         }
590:         return value;
591:     }
592: 
593:     private long toMinor(BigDecimal value) {
594:         return value.movePointRight(2).setScale(0, RoundingMode.UNNECESSARY).longValueExact();
595:     }
596: 
597:     private String normalizeCurrency(String currency) {
598:         String result = currency == null || currency.isBlank() ? "CNY" : currency.trim().toUpperCase();
599:         if (!result.matches("[A-Z]{3}")) throw new IllegalArgumentException("货币代码不合法");
600:         return result;
601:     }
602: 
603:     private void requireOwner(String ownerId) {
604:         if (ownerId == null || ownerId.isBlank()) throw new IllegalArgumentException("用户不能为空");
605:     }
606: }

