132:     private ToolResult<?> queryTransactions(String ownerId, QueryRequest request) {
133:         LocalDate from = parseOptionalDate(request.from(), LocalDate.of(1970, 1, 1), "from");
134:         LocalDate to = parseOptionalDate(request.to(), LocalDate.of(9999, 12, 31), "to");
135:         if (from.isAfter(to)) throw new IllegalArgumentException("from 不能晚于 to");
136:         int limit = request.limit() == null ? 50 : request.limit();
137:         if (limit < 1 || limit > MAX_RESULTS) throw new IllegalArgumentException("limit 必须在 1 至 100 之间");
138:         String keyword = clean(request.keyword()).toLowerCase(Locale.ROOT);
139:         List<FinanceTransaction> transactions = financeService.getTransactions(ownerId).stream()
140:                 .filter(item -> !item.date().isBefore(from) && !item.date().isAfter(to))
141:                 .filter(item -> isBlank(request.accountId()) || item.accountId().equals(request.accountId()))
142:                 .filter(item -> isBlank(request.transactionType()) || item.transactionType().equals(request.transactionType()))
143:                 .filter(item -> isBlank(request.category()) || item.category().equals(request.category()))
144:                 .filter(item -> keyword.isEmpty()
145:                         || item.note().toLowerCase(Locale.ROOT).contains(keyword)
146:                         || item.category().toLowerCase(Locale.ROOT).contains(keyword))
147:                 .limit(limit + 1L)
148:                 .toList();
