51:     public ExpenseAnalysis analyze(String ownerId, LocalDate from, LocalDate to) {
52:         validate(ownerId, from, to);
53:         List<ExpenseEntry> entries = findExpenses(ownerId, from, to);
54:         Map<LocalDate, List<ExpenseEntry>> byDate = new LinkedHashMap<>();
55:         for (LocalDate date = from; !date.isAfter(to); date = date.plusDays(1)) {
56:             byDate.put(date, new ArrayList<>());
57:         }
58:         entries.forEach(entry -> byDate.get(entry.date()).add(entry));
59: 
60:         List<ExpenseDay> days = byDate.entrySet().stream().map(item -> {
61:             Map<String, BigDecimal> categories = new LinkedHashMap<>();
62:             BigDecimal total = BigDecimal.ZERO;
63:             int financeCount = 0;
64:             String financeHeadline = null;
65:             for (ExpenseEntry entry : item.getValue()) {
66:                 total = total.add(entry.amount());
67:                 categories.merge(entry.category(), entry.amount(), BigDecimal::add);
68:                 if ("finance".equals(entry.source())) {
69:                     financeCount++;
70:                     if (financeHeadline == null) financeHeadline = entry.note();
71:                 }
72:             }
73:             return new ExpenseDay(item.getKey(), total, categories, financeCount, financeHeadline);
74:         }).toList();
75:         BigDecimal total = days.stream().map(ExpenseDay::total).reduce(BigDecimal.ZERO, BigDecimal::add);
76:         return new ExpenseAnalysis(from, to, total, days);
77:     }
