160:     private List<ExpenseEntry> findExpenses(String ownerId, LocalDate from, LocalDate to) {
161:         return jdbcTemplate.query("""
162:                 SELECT id, expense_date, expense_time, category, note, amount_minor, currency, source, created_at
163:                 FROM (
164:                     SELECT e.id AS id, e.event_date AS expense_date, x.expense_time AS expense_time,
165:                            x.category AS category, x.note AS note, x.amount_minor AS amount_minor,
166:                            x.currency AS currency, 'calendar' AS source, e.created_at AS created_at
167:                     FROM daily_event e
168:                     JOIN expense_detail x ON x.event_id = e.id
169:                     WHERE e.owner_id = ? AND e.event_date BETWEEN ? AND ?
170:                     UNION ALL
171:                     SELECT t.id AS id, t.transaction_date AS expense_date, t.transaction_time AS expense_time,
172:                            t.category AS category, t.note AS note, t.amount_minor AS amount_minor,
173:                            t.currency AS currency, 'finance' AS source, t.created_at AS created_at
174:                     FROM finance_transaction t
175:                     WHERE t.owner_id = ? AND t.transaction_type = 'expense'
176:                       AND t.transaction_date BETWEEN ? AND ?
177:                 ) expenses
178:                 ORDER BY expense_date, expense_time, created_at, id
179:                 """, (resultSet, rowNumber) -> new ExpenseEntry(
180:                 resultSet.getString("id"), LocalDate.parse(resultSet.getString("expense_date")),
181:                 LocalTime.parse(resultSet.getString("expense_time")), resultSet.getString("category"),
182:                 resultSet.getString("note"), BigDecimal.valueOf(resultSet.getLong("amount_minor"), 2),
183:                 resultSet.getString("currency"), resultSet.getString("source"),
184:                 Instant.parse(resultSet.getString("created_at"))),
185:                 ownerId, from.toString(), to.toString(), ownerId, from.toString(), to.toString());
186:     }
