201: export function FinanceMiniTile({ date, refreshKey, onOpenFinance }: Pick<FinanceTilesProps, 'date' | 'refreshKey' | 'onOpenFinance'>) {
202:   const load = useCallback(async () => {
203:     const overview = await fetchFinanceOverview();
204:     return overview;
205:   }, []);
206:   const { data, loading, error, reload } = useOverviewResource(load, `${date}:${refreshKey}`);
207:   const [selected, setSelected] = useState<FinanceTransaction | null>(null);
208: 
209:   return (
210:     <>
211:       <section className={`${styles.tile} ${styles.financeMini}`}>
212:         <div className={styles.tileHead} style={{ marginBottom: 4 }}>
213:           <div>
214:             <div className={styles.eyebrow}>RECENT</div>
215:             <div className={styles.title}>最近流水</div>
216:           </div>
217:           <span className={styles.pill} onClick={onOpenFinance}>查看全部</span>
218:         </div>
219: 
220:         {loading ? (
221:           <p className={styles.empty}>正在加载流水…</p>
222:         ) : error ? (
223:           <p className={styles.error} onClick={() => void reload()}>{error}</p>
224:         ) : data && data.transactions.length === 0 ? (
225:           <p className={styles.empty}>暂无流水记录。</p>
226:         ) : data ? (
227:           data.transactions.slice(0, 3).map((item) => {
228:             const isAdjustment = item.transactionType === 'adjustment_increase'
229:               || item.transactionType === 'adjustment_decrease';
230:             const isOut = item.transactionType === 'expense'
231:               || item.transactionType === 'transfer_out'
232:               || item.transactionType === 'adjustment_decrease';
233:             return (
234:               <button
235:                 type="button"
236:                 key={item.id}
237:                 className={styles.flowRow}
238:                 onClick={() => setSelected(item)}
239:               >
240:                 <div>
241:                   <div className={styles.flowName}>{item.note || item.category}</div>
242:                   <div className={styles.flowMeta}>{item.accountName} · {item.time}</div>
243:                 </div>
244:                 <div className={`${styles.flowMoney} ${isAdjustment ? styles.adjustment : isOut ? styles.out : styles.in}`}>
245:                   {isOut ? '−' : '+'}{money(item.amount, item.currency)}
246:                 </div>
247:               </button>
248:             );
249:           })
250:         ) : null}
251:       </section>
252: 
253:       <Modal open={selected !== null} title="流水详情" onClose={() => setSelected(null)} centered width={480}>
254:         {selected && (
255:           <>
256:             <div className={styles.metric}>
257:               <strong>{selected.transactionType === 'expense'
258:                 || selected.transactionType === 'transfer_out'
259:                 || selected.transactionType === 'adjustment_decrease' ? '−' : '+'}{money(selected.amount, selected.currency)}</strong>
260:               <span>{selected.transactionType === 'expense'
261:                 ? '支出'
262:                 : selected.transactionType === 'yield'
263:                 ? '收益'
264:                 : selected.transactionType === 'transfer_out' || selected.transactionType === 'transfer_in'
265:                 ? '划账'
266:                 : selected.transactionType === 'adjustment_increase' || selected.transactionType === 'adjustment_decrease'
267:                 ? '余额校准（非收支）'
268:                 : '收入'}</span>
269:             </div>
270:             <p>{selected.note || selected.category}</p>
271:             <dl className={styles.stats}>
272:               <div><dt>账户</dt><dd>{selected.accountName}</dd></div>
273:               <div><dt>分类</dt><dd>{selected.category}</dd></div>
274:               <div><dt>发生时间</dt><dd>{selected.date} {selected.time}</dd></div>
275:             </dl>
276:           </>
277:         )}
278:       </Modal>
279:     </>
280:   );
281: }
