27:     /** 创建启用外键、WAL 和锁等待的 SQLite 数据源。 */
28:     @Bean
29:     public DataSource localDataSource(LocalDatabaseProperties properties) {
30:         Path databasePath = properties.getPath().toAbsolutePath().normalize();
31:         Path parent = databasePath.getParent();
32:         if (parent == null) {
33:             throw new IllegalStateException("SQLite 数据库路径必须包含父目录");
34:         }
35:         try {
36:             Files.createDirectories(parent);
37:         } catch (IOException exception) {
38:             throw new IllegalStateException("无法创建本地数据库目录: " + parent, exception);
39:         }
40: 
41:         SQLiteConfig config = new SQLiteConfig();
42:         config.enforceForeignKeys(true);
43:         config.setJournalMode(SQLiteConfig.JournalMode.WAL);
44:         config.setSynchronous(SQLiteConfig.SynchronousMode.NORMAL);
45:         config.setBusyTimeout(5_000);
46: 
47:         SQLiteDataSource dataSource = new SQLiteDataSource(config);
48:         dataSource.setUrl("jdbc:sqlite:" + databasePath);
49:         return dataSource;
