import type { ChatMessage, TranscriptMessageDto } from '../../types/chat';

function padTwo(value: number): string {
  return String(value).padStart(2, '0');
}

/** 将毫秒时间戳格式化为本地日期时间（精确到秒）：YYYY-MM-DD HH:mm:ss。 */
export function formatMessageTimestampSeconds(timestamp: number): string {
  if (!Number.isFinite(timestamp) || timestamp <= 0) return '';
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '';
  return `${date.getFullYear()}-${padTwo(date.getMonth() + 1)}-${padTwo(date.getDate())} `
    + `${padTwo(date.getHours())}:${padTwo(date.getMinutes())}:${padTwo(date.getSeconds())}`;
}

/**
 * 判断一条历史/后端消息是否属于 Agent 主动推送消息。
 * 优先认服务端显式 proactive 标记；旧记录缺少该字段时，按“无同轮 USER 消息且无模型耗时/用量”识别。
 */
export function isProactiveTranscriptMessage(
  dto: TranscriptMessageDto,
  userTurnIds?: Set<string> | TranscriptMessageDto[],
): boolean {
  if (dto.role?.toUpperCase() !== 'ASSISTANT') return false;
  if (dto.proactive === true) return true;
  if (dto.proactive === false && !userTurnIds) return false;
  if (!dto.turnId || dto.status !== 'COMPLETED') return false;
  if ((dto.durationMillis ?? 0) !== 0 || dto.usage || dto.thinking) return false;
  if (dto.tools && dto.tools.length > 0) return false;
  if (!userTurnIds) return false;
  if (userTurnIds instanceof Set) {
    return !userTurnIds.has(dto.turnId);
  }
  return !userTurnIds.some((item) => item.role?.toUpperCase() === 'USER' && item.turnId === dto.turnId);
}

export function mapTranscriptToChatMessage(
  dto: TranscriptMessageDto,
  _index?: number,
  allMessages?: TranscriptMessageDto[],
  userTurnIds?: Set<string>,
): ChatMessage {
  const isUser = dto.role?.toUpperCase() === 'USER';
  const proactive = isUser ? false : isProactiveTranscriptMessage(dto, userTurnIds ?? allMessages);
  const parsedTime = dto.createdAt ? new Date(dto.createdAt).getTime() : NaN;
  const createdAt = Number.isFinite(parsedTime) && parsedTime > 0
    ? parsedTime
    : (proactive ? 0 : Date.now());
  return {
    id: dto.id,
    turnId: dto.turnId,
    role: isUser ? 'user' : 'assistant',
    modelName: isUser ? undefined : 'ButvanAgent',
    content: dto.content || '',
    reasoning: dto.thinking || undefined,
    createdAt,
    status: dto.status,
    usage: dto.usage,
    proactive: proactive || undefined,
    elapsedTime:
      dto.durationMillis != null
        ? Math.max(1, Math.round(dto.durationMillis / 1000))
        : undefined,
    tools:
      dto.tools && dto.tools.length > 0
        ? dto.tools.map((t) => ({
            toolCallId: t.toolCallId,
            toolName: t.toolName,
            command: t.command,
            output: t.output,
            status: (t.status ? t.status.toLowerCase() : 'completed') as
              | 'running'
              | 'completed'
              | 'failed'
              | 'cancelled',
          }))
        : undefined,
  };
}

/** 批量映射整段会话记录，一次建立用户轮次索引以 O(n) 识别历史主动推送消息。 */
export function mapTranscriptMessages(dtos: TranscriptMessageDto[]): ChatMessage[] {
  const userTurnIds = new Set<string>();
  for (const dto of dtos) {
    if (dto.role?.toUpperCase() === 'USER' && dto.turnId) {
      userTurnIds.add(dto.turnId);
    }
  }
  return dtos.map((dto, index) => mapTranscriptToChatMessage(dto, index, dtos, userTurnIds));
}

import React, { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react';
import { readPreference, writePreference } from '../services/desktopPreferences';

const SIDEBAR_COLLAPSED_KEY = 'butvan.sidebarCollapsed';

interface SidebarLayoutContextValue {
  collapsed: boolean;
  canToggle: boolean;
  collapse: () => void;
  expand: () => void;
  toggle: () => void;
}

const DEFAULT_VALUE: SidebarLayoutContextValue = {
  collapsed: false,
  canToggle: false,
  collapse: () => {},
  expand: () => {},
  toggle: () => {},
};

const SidebarLayoutContext = createContext<SidebarLayoutContextValue>(DEFAULT_VALUE);

function readInitialCollapsed(): boolean {
  try {
    return readPreference(SIDEBAR_COLLAPSED_KEY) === 'true';
  } catch {
    return false;
  }
}

export const SidebarLayoutProvider: React.FC<{ children: ReactNode; disabled?: boolean }> = ({
  children,
  disabled = false,
}) => {
  const [collapsed, setCollapsed] = useState<boolean>(readInitialCollapsed);

  const persist = useCallback((next: boolean) => {
    try {
      writePreference(SIDEBAR_COLLAPSED_KEY, String(next));
    } catch {
      // 忽略本地偏好写入异常
    }
  }, []);

  const collapse = useCallback(() => {
    setCollapsed(true);
    persist(true);
  }, [persist]);

  const expand = useCallback(() => {
    setCollapsed(false);
    persist(false);
  }, [persist]);

  const toggle = useCallback(() => {
    setCollapsed((prev) => {
      const next = !prev;
      persist(next);
      return next;
    });
  }, [persist]);

  useEffect(() => {
    const activeCollapsed = !disabled && collapsed;
    document.documentElement.dataset.sidebarCollapsed = activeCollapsed ? 'true' : 'false';
    return () => {
      delete document.documentElement.dataset.sidebarCollapsed;
    };
  }, [collapsed, disabled]);

  useEffect(() => {
    if (disabled) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.isComposing) return;
      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.shiftKey || event.code !== 'KeyB') {
        return;
      }
      const target = event.target as HTMLElement | null;
      if (target && (target.isContentEditable || target.closest('[contenteditable="true"]'))) {
        return;
      }
      event.preventDefault();
      toggle();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [disabled, toggle]);

  return (
    <SidebarLayoutContext.Provider value={{ collapsed, canToggle: true, collapse, expand, toggle }}>
      {children}
    </SidebarLayoutContext.Provider>
  );
};

export function useSidebarLayout(): SidebarLayoutContextValue {
  return useContext(SidebarLayoutContext);
}

import { useEffect, useRef, useState, type RefObject } from 'react';
import { readPreference, writePreference } from '../../services/desktopPreferences';

export const SIDEBAR_DEFAULT_WIDTH = 260;
const SIDEBAR_MIN_WIDTH = 220;
const SIDEBAR_MAX_WIDTH = 400;
const SIDEBAR_WIDTH_KEY = 'butvan.sidebarWidth';

/** 管理侧边栏拖拽宽度调整与本地偏好持久化。 */
export function useSidebarWidth(sidebarRef: RefObject<HTMLElement | null>) {
  const [sidebarWidth, setSidebarWidth] = useState<number>(() => {
    try {
      const saved = Number(readPreference(SIDEBAR_WIDTH_KEY));
      if (saved >= SIDEBAR_MIN_WIDTH && saved <= SIDEBAR_MAX_WIDTH) {
        return saved;
      }
    } catch {
      // 忽略本地存储异常，使用默认宽度
    }
    return SIDEBAR_DEFAULT_WIDTH;
  });
  const sidebarWidthRef = useRef(sidebarWidth);
  sidebarWidthRef.current = sidebarWidth;
  const [isResizing, setIsResizing] = useState(false);

  useEffect(() => {
    if (!isResizing) return;

    const onMouseMove = (e: MouseEvent) => {
      const rect = sidebarRef.current?.getBoundingClientRect();
      if (!rect) return;
      const next = Math.min(
        SIDEBAR_MAX_WIDTH,
        Math.max(SIDEBAR_MIN_WIDTH, Math.round(e.clientX - rect.left)),
      );
      setSidebarWidth(next);
    };

    const onMouseUp = () => {
      setIsResizing(false);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      try {
        writePreference(SIDEBAR_WIDTH_KEY, String(sidebarWidthRef.current));
      } catch {
        // 忽略本地存储异常
      }
    };

    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isResizing, sidebarRef]);

  return {
    sidebarWidth,
    isResizing,
    startResizing: () => setIsResizing(true),
    resetWidth: () => setSidebarWidth(SIDEBAR_DEFAULT_WIDTH),
  };
}

import React from 'react';
