/** 当左侧边栏已收起时，在主工作区顶栏左侧渲染展开入口。 */
export const SidebarExpandButton: React.FC = () => {
  const { collapsed, canToggle, expand } = useSidebarLayout();
  if (!canToggle || !collapsed) return null;

  return (
    <button
